orm", ["spell:71"] = "Defensive Stance", ["zone:1412"] = "Mulgore", ["zone:1413"] = "Barrens", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff", ["zone:2521"] = "Zephras Isle" },
			written = { ["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit by Raan's campfire until you get Boosted Rest", ["Back to {npc:268592}, then west into the {area:16623}: {npc:268605}'s home is in the hills south of the Windsong Crawlers' lakes."] = "Back to Olariaan, then west into the Shen'dar Highlands: Kuramaa's home is in the hills south of the Windsong Crawlers' lakes.", ["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Back to Olariaan. Wait for him to light the Brazier of Offering, then carry the flame straight to the Brazier of Eternal Flame beside Sessaria in Valanaar before the timer runs out.", ["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Head north into Shadowgale Forest; Elegael camps at its southern edge.", ["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Jump off the top of the watchtower and use Walk on Air to float down to Rorian, west of the tower.", ["Leave {zone:1456} by a lift and follow the road south past {area:222} and through the eastern pass into the {zone:1413}; from the pass, take the {area:458} north to the {area:380}, the Horde town in the middle of the {zone:1413}."] = "Leave Thunder Bluff by a lift and follow the road south past Bloodhoof Village and through the eastern pass into the Barrens; from the pass, take the Gold Road north to the Crossroads, the Horde town in the middle of the Barrens.", ["Prideclaws and Galestriders share the meadows south of the village. Keep the {item:5469} for {npc:251905}; the eggs come later from the hippogryphs."] = "Prideclaws and Galestriders share the meadows south of the village. Keep the Strider Meat for Zerril; the eggs come later from the hippogryphs.", ["Sit by {npc:263664}'s campfire (type /sit) until you get the {spell:1229451} buff, then find {npc:251905} at the cook fire."] = "Sit by Raan's campfire (type /sit) until you get the Boosted Rest buff, then find Zerril Softbreeze at the cook fire.", ["Take the portal up to the {area:16630} and join {npc:252475} and {npc:251968} against the High Priestess."] = "Take the portal up to the Rohashi Spires and join Elaadrin and Ayessa against the High Priestess.", ["Take the road south-east to {area:16638}, the Skyborne town on the south coast. {npc:257006} and {npc:252448} stand at its western edge."] = "Take the road south-east to Valanaar, the Skyborne town on the south coast. Nyalah and Alvarion stand at its western edge.", ["The Al'Aketh cultists in the camp beyond {npc:252095} carry the signet."] = "The Al'Aketh cultists in the camp beyond Hanaa carry the signet.", ["The last {object:616466}, the Enchanted Gyrozephyrs, lie far to the north, east of {area:16624} and south-west of {area:16625}. Then head back south-west to {npc:252800} at the orchard."] = "The last Construct Parts, the Enchanted Gyrozephyrs, lie far to the north, east of Shen'dar Village and south-west of Windsong Lake. Then head back south-west to Aamelia at the orchard.", ["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "You wake in Thendal Village, in the north of the isle. Ailee stands by the path, Rorian at the village centre.", ["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "Lady's Tear Moss grows around Elegael's camp and Shriekings fly over it. The Al'Aketh camp east of her holds the Bloody Heirloom.", ["{npc:250926} prowl the slopes south-west of the village, on the way to {npc:252095}."] = "Scrawny Ursera prowl the slopes south-west of the village, on the way to Hanaa.", ["{npc:251361}'s errands"] = "Rorian's errands", ["{npc:251361}: examine the {item:282418}"] = "Rorian: examine the Humming Recall Crystal", ["{npc:251361}: {quest:92485}"] = "Rorian: A Student of Nature", ["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "Xyton Silverwind, the druid trainer, on the ground floor of the tree behind Rorian", ["{npc:252095} waits in {area:16622}, south-west of the village. The Al'Aketh camp is just beyond her; {npc:256935} leads it."] = "Hanaa waits in Thendal Grove, south-west of the village. The Al'Aketh camp is just beyond her; Malduko Cloudcrush leads it.", ["{npc:252359} stands on {area:16638}'s east side."] = "Lotheluum stands on Valanaar's east side.", ["{npc:252448} and {npc:256083}"] = "Alvarion and Riaani", ["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "Commander Haalien, Jorel Windsinger and Naaleos Leafwhisper are in the cult camp east of Elegael. Vayn Moongaze stands at its edge. Haalien also drops a Ripped Missive: read it to start the next quest. For The Wounds of Betrayal, enter the Nightfang Den, heal 7 injured druids and find Jorel.", ["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "Vulgara lurks south of the village, among the Prideclaws. Vulgara is elite: grouping up is advised.", ["{npc:256083} stands in the {area:16626} just north-west of town."] = "Riaani stands in the Gustberry Lowlands just north-west of town.", ["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "Belathaan waits on the road north of Valanaar, towards the Shrine of Akir.", ["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "Halaan Hawk-Eye and Myriaal Mistwake stand at the top of the watchtower, a few steps north-east of Elatrell.", ["{npc:257944} again"] = "Elegael again", ["{npc:263664}'s campfire"] = "Raan's campfire", ["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "Eylah Sunhorn wants tauren incense: buy its four parts from Nida the herbalist, Nata the enchanting supplier, Mahu the leatherworking supplier and Naal the cooking supplier, then combine them into Prepared Incense." },
