			written = { ["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Prairie Wolf Alphas roam among the wolves on the plains around Malah and the Galak camp to the east.", ["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Ride a lift up to the mesas. Tal keeps the wind riders on the central rise; Cairne stands in the great tent there.", ["The Galak centaurs camp on the plains east of the well; {npc:275767} leads them."] = "The Galak centaurs camp on the plains east of the well; Herak leads them.", ["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "You start on the mesa of Camp Narache. Grull and the chief stand by the big tent in the middle.", ["{area:380}"] = "The Crossroads", ["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "Eylah Sunhorn wants tauren incense: buy its four parts from Nida the herbalist, Nata the enchanting supplier, Mahu the leatherworking supplier and Naal the cooking supplier, then combine them into Prepared Incense.", ["{npc:275789} stands on the {area:821} a little east of the well."] = "Malah stands on the Rolling Plains a little east of the well.", ["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "Ahab stands at the north edge of the village. Kyle wants Tender Strider Meat from plainstriders.", ["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "Morin camps by the Winterhoof Water Well south-east of Bloodhoof.", ["{npc:2993}, for {npc:3057} in {zone:1456}"] = "Baine Bloodhoof, for Cairne in Thunder Bluff", ["{npc:3209}, next to {npc:2980}"] = "Brave Windfeather, next to Grull", ["{npc:6746} on the central rise sends you to {npc:3033} on {area:1639}."] = "Innkeeper Pala on the central rise sends you to Turak on Elder Rise.", ["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "Antur Fallow stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to Grull." },
