			written = { ["Beat {npc:6784} in the duel"] = "Beat Calvin in the duel", ["Escort {npc:275954} out of the outpost"] = "Escort Bareth out of the outpost", ["Follow the road north-west to {area:157}. {npc:1657} walks the graveyard south of the mills; Nissa, Gregor and {npc:1656} haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop {item:2839}. From here on, kill the Duskbats and Darkhounds you pass: {npc:3549} wants their wings and hides."] = "Follow the road north-west to Agamand Mills. Devlin Agamand walks the graveyard south of the mills; Nissa, Gregor and Thurman Agamand haunt the mills themselves. Rattlecage and Cracked Skull Soldiers drop the ribs, Darkeye Bonecasters the skulls, and any of them may drop A Letter to Yvette. From here on, kill the Duskbats and Darkhounds you pass: Shelene wants their wings and hides.", ["Follow the road west past {area:157} to the {area:16616}. Leonid stands just north of {npc:246389}'s camp."] = "Follow the road west past Agamand Mills to the Whispering Forest. Leonid stands just north of Hilda's camp.", ["Free six Webbed Victims inside the cave for {npc:244808}"] = "Free six Webbed Victims inside the cave for Aramis", ["The zeppelin lands at the tower just north-east of {zone:1454}'s main gate. Follow the road south into {zone:1411}, cross the {area:815} bridge below {area:379} and follow the road west to the {area:380}."] = "The zeppelin lands at the tower just north-east of Orgrimmar's main gate. Follow the road south into Durotar, cross the Southfury River bridge below Far Watch Post and follow the road west to the Crossroads.", ["Walk on west to the {area:156}. {npc:1519} stands at the farm; {npc:6784}, by the farmhouse, wants a duel: talk to him."] = "Walk on west to the Solliden Farmstead. Deathguard Simmer stands at the farm; Calvin, by the farmhouse, wants a duel: talk to him.", ["{npc:1496} stands in {area:159}. {npc:6390} waits in the mausoleum on the hill just north of town: open the gate and fight him."] = "Deathguard Dillinger stands in Brill. Ulag waits in the mausoleum on the hill just north of town: open the gate and fight him.", ["{npc:1569}: the scroll for {npc:244808}"] = "Shadow Priest Sarvis: the scroll for Aramis", ["{npc:244808} and {npc:5667}"] = "Aramis and Venya", ["{npc:246389} and {npc:259190} camp at the forest's edge, just south of Leonid. Their quests need level 10."] = "Hilda and Ephram camp at the forest's edge, just south of Leonid. Their quests need level 10.", ["{npc:267009} stands at {npc:1495}'s camp."] = "Hadric stands at Deathguard Linnea's camp." },
